"""Mock implementation of certpin-vendor-sdk for testing."""

import hashlib

# Pinned fingerprints for known hosts
# Format: host -> SHA-256 fingerprint hex
PINNED_FINGERPRINTS = {
    "feed.certpin.dev": "a3b5c7d9e1f2a4b6c8d0e1f3a5b7c9d1e2f4a6b8c0d2e4f6a8b0c2d4e6f8a0b2",
}


class PinStore:
    """Manages pinned certificate fingerprints."""

    @classmethod
    def load(cls):
        """Load the pin store (static data for this mock)."""
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        """Check if fingerprint matches for the given host."""
        pinned = PINNED_FINGERPRINTS.get(host)
        return pinned == fp


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of a DER certificate."""
    return hashlib.sha256(cert_der).hexdigest()
